/** One library in the third-party license list (generated by scripts/licenses.mjs). */
export interface LicenseEntry {
  name: string;
  version: string;
  /** SPDX expression as the package declares it ("MIT OR Apache-2.0"). */
  license: string;
  /** Indices into `Licenses.texts`. */
  texts: number[];
}

export interface Licenses {
  format: number;
  inputs: Record<string, string>;
  rust: LicenseEntry[];
  javascript: LicenseEntry[];
  texts: string[];
}

const isEntry = (e: unknown): e is LicenseEntry =>
  typeof e === "object" &&
  e !== null &&
  typeof (e as LicenseEntry).name === "string" &&
  typeof (e as LicenseEntry).version === "string" &&
  typeof (e as LicenseEntry).license === "string" &&
  Array.isArray((e as LicenseEntry).texts) &&
  (e as LicenseEntry).texts.every((i) => Number.isInteger(i));

/** Parses the file; throws on anything that is not the generated shape. */
export function parseLicenses(raw: string): Licenses {
  const data = JSON.parse(raw) as Licenses;
  if (
    data?.format !== 1 ||
    !Array.isArray(data.rust) ||
    !Array.isArray(data.javascript) ||
    !Array.isArray(data.texts) ||
    !data.rust.every(isEntry) ||
    !data.javascript.every(isEntry) ||
    !data.texts.every((t) => typeof t === "string")
  ) {
    throw new Error("the license file does not have the expected shape");
  }
  return data;
}

/** Loads the list on demand: it is its own chunk, never part of the main bundle, and no request leaves the app. */
export async function loadLicenses(): Promise<Licenses> {
  const { default: raw } = await import("./licenses.json?raw");
  return parseLicenses(raw);
}
